// AMC 8 / 10 / 12, AHSME and AIME practice bank. Generated by
// `npm run amc:import` (scripts/import-amc-trivial.mjs) — never hand-edit the JSON.

export type AmcContest = 'amc8' | 'amc10' | 'amc12' | 'ahsme' | 'aime';
export type AmcLetter = 'A' | 'B' | 'C' | 'D' | 'E';

export const AMC_CONTESTS: { id: AmcContest; label: string }[] = [
  { id: 'amc8', label: 'AMC 8' },
  { id: 'amc10', label: 'AMC 10' },
  { id: 'amc12', label: 'AMC 12' },
  { id: 'aime', label: 'AIME' },
  { id: 'ahsme', label: 'AHSME' },
];

/** Contests answered with a number (000–999) instead of choices A–E. */
export const isNumeric = (c: AmcContest) => c === 'aime';
export const AMC_LETTERS: AmcLetter[] = ['A', 'B', 'C', 'D', 'E'];

export interface AmcProblem {
  /** `${testId}-${nn}`, e.g. "2023-amc10a-05" */
  id: string;
  /** e.g. "2023-amc10a", "2021-amc12fb" (Fall B), "2001-amc10" */
  test: string;
  /** Problem number (1–25 on AMC, 1–15 on AIME, up to 50 on AHSME). */
  n: number;
  /** Statement: Markdown with $LaTeX$ and ![figure](...) images. */
  q: string;
  /** Five answer choices in LaTeX (no $); empty for AIME. */
  choices: string[];
  /** Letter A–E, or a 3-digit number for AIME ("073"). */
  a: string;
  /** Other accepted answers (AIME), e.g. ["081"]. */
  alt?: string[];
}

export interface AmcTest {
  id: string;
  title: string;
  contest: AmcContest;
  year: number;
  problems: AmcProblem[];
}

/** Extra fields derived from the test id, attached at load time. */
export interface AmcItem extends AmcProblem {
  contest: AmcContest;
  year: number;
  /** "A" | "B" | "Fall A" | "Fall B" | "P" | "I" | "II" | "" (single-date years) */
  sitting: string;
  title: string;
  /** Number of problems in the test (for position-based difficulty). */
  total: number;
}

const modules = import.meta.glob<AmcTest>('./bank/*.json', { import: 'default' });

export const AMC_TEST_COUNT = Object.keys(modules).length;

export function sittingOf(testId: string): string {
  const aime = testId.match(/aime(i{1,2})$/);
  if (aime) return aime[1].toUpperCase();
  const m = testId.match(/amc(?:8|10|12)(f?)([abp]?)$/);
  if (!m || !m[2]) return '';
  return `${m[1] ? 'Fall ' : ''}${m[2].toUpperCase()}`;
}

/** Is `answer` right? Letters compare exactly; AIME numbers compare as integers. */
export function isCorrect(p: AmcProblem, answer: string): boolean {
  if (!/^\d+$/.test(p.a)) return answer === p.a;
  const n = Number(answer.trim());
  return answer.trim() !== '' && [p.a, ...(p.alt ?? [])].some((x) => Number(x) === n);
}

export async function loadAmcBank(): Promise<AmcItem[]> {
  const tests = await Promise.all(Object.values(modules).map((load) => load()));
  return tests.flatMap((t) =>
    t.problems.map((p) => ({
      ...p,
      contest: t.contest,
      year: t.year,
      sitting: sittingOf(t.id),
      title: t.title,
      total: Math.max(...t.problems.map((x) => x.n)),
    })),
  );
}

const solutionModules = import.meta.glob<Record<string, string>>('./solutions/*.json', { import: 'default' });

/** Solutions (Markdown) for one test, keyed by problem number; loaded on demand. */
export async function loadSolutions(testId: string): Promise<Record<string, string>> {
  const load = solutionModules[`./solutions/${testId}.json`];
  return load ? load() : {};
}

/** AoPS wiki solution page for a problem. */
export function solutionUrl(p: AmcItem): string {
  return `https://artofproblemsolving.com/wiki/index.php/${encodeURIComponent(`${p.title} Problems/Problem ${p.n}`.replace(/ /g, '_')).replace(/%2F/g, '/')}`;
}

/** Ids of the tests in the bank (from the JSON file names). */
export const AMC_TEST_IDS: Set<string> = new Set(
  Object.keys(modules).map((k) => k.replace(/^.*\/(.+)\.json$/, '$1')),
);

export interface AmcTestRef {
  id: string;
  contest: AmcContest;
  year: number;
  /** Wiki title stem, e.g. "2023 AMC 12A", "2021 Fall AMC 10B" */
  title: string;
}

/** Every AMC test the AoPS wiki has, for the "Add tests" checklist (newest first). */
export function allAmcTests(contest: AmcContest, fromYear = 0): AmcTestRef[] {
  const now = new Date().getFullYear();
  const out: AmcTestRef[] = [];
  const add = (year: number, suffix: string, title: string) =>
    out.push({ id: `${year}-${contest}${suffix}`, contest, year, title });
  if (contest === 'amc8') {
    for (let y = 1999; y <= now; y++) if (y !== 2021) add(y, '', `${y} AMC 8`);
  } else {
    const label = contest === 'amc10' ? 'AMC 10' : 'AMC 12';
    add(2000, '', `2000 ${label}`);
    add(2001, '', `2001 ${label}`);
    for (let y = 2002; y <= now; y++) {
      add(y, 'a', `${y} ${label}A`);
      add(y, 'b', `${y} ${label}B`);
      if (y === 2021) {
        add(y, 'fa', `2021 Fall ${label}A`);
        add(y, 'fb', `2021 Fall ${label}B`);
      }
    }
  }
  return out.filter((t) => t.year >= fromYear).reverse();
}

export function wikiUrl(title: string): string {
  return `https://artofproblemsolving.com/wiki/index.php/${title.replace(/ /g, '_')}`;
}
